const rows = $input.first().json.rows || $input.first().json.body?.rows || [];

const contacts = [];
const companies = [];
const seenDomains = new Set();

for (const row of rows) {
  const email = (row.email || '').trim().toLowerCase();
  if (!email) continue;

  contacts.push({
    email,
    firstname: row.firstname || row.first_name || '',
    lastname: row.lastname || row.last_name || '',
    jobtitle: row.jobtitle || row.clay_title_inferred || '',
    company: row.company || row.clay_company_name || '',
    hs_lead_status: row.hs_lead_status || 'NEW',
    lifecyclestage: row.lifecyclestage || 'marketingqualifiedlead',
    icp_tier: row.icp_tier || row.clay_icp_tier || 'unscored',
    hubspot_owner_email: row.hubspot_owner_email || ''
  });

  const domain = email.split('@')[1] || '';
  if (domain && !seenDomains.has(domain)) {
    seenDomains.add(domain);
    companies.push({
      domain,
      name: row.company || row.clay_company_name || '',
      numberofemployees: row.clay_company_size || '',
      industry: row.clay_industry || ''
    });
  }
}

const eventSlug = $('Webinar Ended (webhook)').item.json.body.event_slug || 'unknown-event';
const eventTag = $('Webinar Ended (webhook)').item.json.body.event_tag || eventSlug;

return [{ json: { contacts, companies, eventSlug, eventTag } }];

const companies = $json.companies || [];
if (companies.length === 0) return [{ json: { _empty: true } }];
return companies.map(c => ({ json: c }));

const rows = $input.all().map(i => i.json).filter(r => !r._empty);
return [{ json: { inputs: rows.map(r => ({
  idProperty: 'domain',
  id: r.domain,
  properties: { domain: r.domain, name: r.name, numberofemployees: r.numberofemployees, industry: r.industry }
})) } }];

const contacts = $json.contacts || [];
if (contacts.length === 0) return [{ json: { _empty: true } }];
return contacts.map(c => ({ json: c }));

const rows = $input.all().map(i => i.json).filter(r => !r._empty);
return [{ json: { inputs: rows.map(r => ({
  idProperty: 'email',
  id: r.email,
  properties: {
    email: r.email, firstname: r.firstname, lastname: r.lastname, jobtitle: r.jobtitle,
    company: r.company, hs_lead_status: r.hs_lead_status, lifecyclestage: r.lifecyclestage,
    icp_tier: r.icp_tier, hubspot_owner_email: r.hubspot_owner_email
  }
})) } }];

const items = $input.all().map(i => i.json);
const contactResults = items.filter(i => i.properties && i.properties.email);
const companyResults = items.filter(i => i.properties && i.properties.domain);

const idByDomain = {};
for (const co of companyResults) idByDomain[co.properties.domain] = co.id;

const pairs = [];
for (const c of contactResults) {
  const domain = (c.properties.email.split('@')[1] || '').toLowerCase();
  const companyId = idByDomain[domain];
  if (companyId) pairs.push({ from: { id: c.id }, to: { id: companyId } });
}

if (pairs.length === 0) return [{ json: { _empty: true } }];
return pairs.map(p => ({ json: p }));

const closeAtRaw = $('Webinar Ended (webhook)').item.json.body && $('Webinar Ended (webhook)').item.json.body.event_close_at;
let slaHours = null;
let slaNote = 'event_close_at present and parsed cleanly';
if (!closeAtRaw) {
  slaNote = 'event_close_at missing from the original webhook payload -- SLA figure unavailable, downstream copy falls back to a generic phrase instead of a real number';
} else {
  const closeAtMs = Date.parse(closeAtRaw);
  if (isNaN(closeAtMs)) {
    slaNote = 'event_close_at present but not a parseable ISO-8601 timestamp: ' + JSON.stringify(closeAtRaw);
  } else {
    slaHours = (Date.now() - closeAtMs) / 3600000;
  }
}

return $input.all().map(item => ({ json: { ...item.json, sla_hours_after_close: slaHours, sla_note: slaNote } }));

const NL = String.fromCharCode(10);
const NL2 = NL + NL;

const sla = $json.sla_hours_after_close;
const slaLine = (sla === null || sla === undefined)
  ? 'Sent an unknown number of hours after event close (event_close_at was not provided on the webhook payload -- see the SLA stamping node notes).'
  : 'Sent ' + sla.toFixed(1) + 'h after event close.';

const nowIso = new Date().toISOString();

const allContacts = ($('Shape M1 Payload').item.json.contacts) || [];
const attendeeMatch = allContacts.find(c => c.attendance_status === 'attended');
const noShowMatch = allContacts.find(c => c.attendance_status === 'no_show');

const attendeeFallback = { email: 'tivanov@everlinetech.com', firstname: 'Tomas', company: 'Everline Technologies' };
const noShowFallback = { email: 'anunes@northfielddata.com', firstname: 'Amit', company: 'Northfield Data Co' };
const attendeeContact = attendeeMatch || attendeeFallback;
const noShowContact = noShowMatch || noShowFallback;
const speakerContact = { email: 'priya.nair@acmerevenue.example', firstname: 'Priya', lastname: 'Nair', company: 'ACME Revenue Cloud' };

let mergedResults = [];
try {
  mergedResults = $('Merge Contact + Company Results').all().map(i => i.json);
} catch (e) {
  mergedResults = [];
}
const contactResults = mergedResults.filter(r => r.properties && r.properties.email);

const resolveContactId = (email) => {
  if (!email) return null;
  const lower = String(email).toLowerCase();
  const hit = contactResults.find(r => (r.properties.email || '').toLowerCase() === lower);
  return hit ? hit.id : null;
};

const attendeeName = attendeeContact.firstname || 'there';
const attendeeCompany = attendeeContact.company || 'your team';
const attendeeBody = '[DEMO -- would send to: ' + attendeeContact.email + ']' + NL2
  + 'Hi ' + attendeeName + ',' + NL2
  + 'Thanks for spending part of your day with us for Pipeline After the Webinar: Turning Event Engagement into Revenue. With ' + attendeeCompany + ' in the room, that is exactly the kind of team this session was built for.' + NL2
  + 'Follow-up sent within 4 hours of a webinar ending lifts reply rate 3.2x versus next-day -- this email is us following our own advice.' + NL2
  + slaLine + NL2
  + 'Priya Nair' + NL + 'VP Marketing, ACME Revenue Cloud';

const noShowName = noShowContact.firstname || 'there';
const noShowCompany = noShowContact.company || 'your team';
const noShowBody = '[DEMO -- would send to: ' + noShowContact.email + ']' + NL2
  + 'Hi ' + noShowName + ',' + NL2
  + 'Something came up, we understand. Here is the recording of Pipeline After the Webinar: Turning Event Engagement into Revenue, plus the three-bullet version for ' + noShowCompany + ' instead of the full 62 minutes cold.' + NL2
  + 'Speed still matters: follow-up within 4 hours of a session ending lifts reply rate 3.2x versus next-day -- by 48 hours that lift is gone, which is exactly why this is going out now.' + NL2
  + slaLine + NL2
  + 'Priya Nair' + NL + 'VP Marketing, ACME Revenue Cloud';

const speakerBody = '[DEMO -- would send to: ' + speakerContact.email + ']' + NL2
  + 'Hi ' + speakerContact.firstname + ',' + NL2
  + 'Thank you for joining Pipeline After the Webinar: Turning Event Engagement into Revenue. Performance snapshot: 82 live attendees of 150 registered, 35.8 min average watch time.' + NL2
  + 'Build note, not shown to a real recipient: this is a placeholder speaker record. Shape M1 Payload (node 4) does not currently ingest data/incoming/speakers.json, so there is no real speaker data flowing through this n8n lane. A production version would extend Shape M1 Payload to carry speakers, or add a dedicated speakers field on the webhook payload.' + NL2
  + slaLine + NL2
  + 'Priya Nair' + NL + 'VP Marketing, ACME Revenue Cloud';

return [
  { json: { segment: 'attendee', override_to: 'kai8karma+attendee@gmail.com', intended_recipient: attendeeContact.email, subject: (attendeeMatch ? '' : '[fallback contact] ') + 'The 3.2x stat from today session (and your takeaways)', body_text: attendeeBody, contact_id: resolveContactId(attendeeContact.email), sla_hours_after_close: sla, hs_timestamp: nowIso } },
  { json: { segment: 'no_show', override_to: 'kai8karma+noshow@gmail.com', intended_recipient: noShowContact.email, subject: (noShowMatch ? '' : '[fallback contact] ') + 'You registered for a reason -- here is the 6-minute version', body_text: noShowBody, contact_id: resolveContactId(noShowContact.email), sla_hours_after_close: sla, hs_timestamp: nowIso } },
  { json: { segment: 'speaker', override_to: 'kai8karma+speaker@gmail.com', intended_recipient: speakerContact.email, subject: '[placeholder speaker record] Your session numbers are in: 82 attendees, 58% avg watch-through', body_text: speakerBody, contact_id: null, sla_hours_after_close: sla, hs_timestamp: nowIso } }
];

return [{ json: {
  status: 'blocked',
  reason: 'human approval was not granted (body.approved was not true)',
  event_slug: $('Shape M1 Payload').item.json.eventSlug,
  event_tag: $('Shape M1 Payload').item.json.eventTag,
  blocked_at: new Date().toISOString()
} }];

const item = $input.first();
const err = item.json.error || item.json;
return [{ json: {
  status: 'error',
  failing_node: $prevNode?.name || 'unknown',
  message: (err && (err.message || err.description)) || JSON.stringify(err).slice(0, 500),
  event_slug: ($('Shape M1 Payload').first()?.json?.eventSlug) || 'unknown-event',
  execution_id: $execution.id,
  failed_at: new Date().toISOString()
} }];

const closeAtRaw = $('Dispatch Demo (webhook)').item.json.body && $('Dispatch Demo (webhook)').item.json.body.event_close_at;
let slaHours = null;
let slaNote = 'event_close_at present and parsed cleanly';
if (!closeAtRaw) {
  slaNote = 'event_close_at missing from the demo webhook payload -- SLA figure unavailable, copy falls back to a generic phrase';
} else {
  const closeAtMs = Date.parse(closeAtRaw);
  if (isNaN(closeAtMs)) {
    slaNote = 'event_close_at present but not parseable ISO-8601: ' + JSON.stringify(closeAtRaw);
  } else {
    slaHours = (Date.now() - closeAtMs) / 3600000;
  }
}
return $input.all().map(item => ({ json: { ...item.json, sla_hours_after_close: slaHours, sla_note: slaNote } }));

