  + slaLine + NL2
  + 'Priya Nair' + NL + 'VP Marketing, ACME Revenue Cloud';

return [
  { json: { segment: 'attendee', override_to: 'kai8karma+attendee@gmail.com', intended_recipient: attendeeContact.email, subject: 'The 3.2x stat from today session (and your takeaways)', body_text: attendeeBody, sla_hours_after_close: sla, generated_at: nowIso } },
  { json: { segment: 'no_show', override_to: 'kai8karma+noshow@gmail.com', intended_recipient: noShowContact.email, subject: 'You registered for a reason -- here is the 6-minute version', body_text: noShowBody, sla_hours_after_close: sla, generated_at: nowIso } },
