];

const records = $('Demo Build 3 Send Records').all().map(i => i.json);
return $input.all().map((item, idx) => {
  const rec = records[idx] || {};
  return { json: { segment: rec.segment, override_to: rec.override_to, intended_recipient: rec.intended_recipient, subject: rec.subject, sla_hours_after_close: rec.sla_hours_after_close, gmail_message_id: item.json.id || null, gmail_thread_id: item.json.threadId || null, sent_at: new Date().toISOString() } };
});
